from pathlib import Path
import json

root = Path(__file__).resolve().parent / 'source'
planner = (root / 'sidequests.mjs').read_text(encoding='utf-8')
planner = planner.replace("import { randomUUID } from 'node:crypto';", 'const randomUUID = () => crypto.randomUUID();')
planner = planner.replace('export function createPlanner({ request, configured }) {\n  const sessions = new Map();', "function createPlanner({ request, configured, initialSession }) {\n  const sessions = new Map();\n  if (initialSession) { initialSession.rejected = new Set(initialSession.rejected); sessions.set(initialSession.id, initialSession); }")
planner = planner.replace('return { search, plan, repair };', 'return { search, plan, repair, getSession: sessionId => sessions.get(sessionId) };')
assert 'initialSession.rejected = new Set' in planner and 'getSession:' in planner
assets = {f'/{name}': (root / 'public' / name).read_text(encoding='utf-8') for name in ['index.html', 'style.css', 'app.js']}
assets['/'] = assets['/index.html']
wrapper = r'''
const contentTypes = {'/':'text/html; charset=utf-8','/index.html':'text/html; charset=utf-8','/style.css':'text/css; charset=utf-8','/app.js':'text/javascript; charset=utf-8'};
const limits = new Map();
function tooMany(ip) { const now=Date.now(), key=ip||'unknown'; const current=(limits.get(key)||[]).filter(t=>now-t<60000); if(current.length>=20) return true; current.push(now); limits.set(key,current); if(limits.size>1000) for(const [k,v] of limits) if(now-v[v.length-1]>=60000) limits.delete(k); return false; }
function json(status, value) { return new Response(JSON.stringify(value), { status, headers: {'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'} }); }
function b64(bytes) { return btoa(Array.from(bytes, c => String.fromCharCode(c)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function unb64(s) { const x=atob(s.replace(/-/g,'+').replace(/_/g,'/')); return Uint8Array.from(x, c => c.charCodeAt(0)); }
async function cipherKey(secret) { const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('TasteTrail session v1:' + secret)); return crypto.subtle.importKey('raw',hash,'AES-GCM',false,['encrypt','decrypt']); }
async function seal(session,secret) { const iv=crypto.getRandomValues(new Uint8Array(12)); const payload=JSON.stringify({...session,rejected:[...session.rejected],busy:false}); const enc=await crypto.subtle.encrypt({name:'AES-GCM',iv},await cipherKey(secret),new TextEncoder().encode(payload)); return b64(iv)+'.'+b64(new Uint8Array(enc)); }
async function openToken(token,secret) { try { if(typeof token!=='string'||token.length>40000) throw 0; const [a,b,...rest]=token.split('.'); if(!a||!b||rest.length) throw 0; const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(a)},await cipherKey(secret),unb64(b)); const obj=JSON.parse(new TextDecoder().decode(bytes)); if(!obj.id||!Array.isArray(obj.rejected)||!Array.isArray(obj.plan)||!Number.isFinite(obj.updated)||Date.now()-obj.updated>3600000) throw 0; return obj; } catch { throw new Error('This mix has expired or is invalid. Create a new mix.'); } }
function qloo(key) { let next=0; return async (path,params) => { const scheduled=Math.max(Date.now(),next); next=scheduled+260; if(scheduled>Date.now()) await new Promise(r=>setTimeout(r,scheduled-Date.now())); const url=new URL(path,'https://hackathon.api.qloo.com'); for(const [k,v] of Object.entries(params)) url.searchParams.set(k,v); let response; try { response=await fetch(url,{headers:{'X-Api-Key':key,Accept:'application/json'},signal:AbortSignal.timeout(25000),redirect:'error'}); } catch { throw new Error('Could not reach Qloo. Check network access and try again.'); } if(!response.ok) { if(response.status===401||response.status===403) throw new Error('Qloo rejected the API credential. Check the server configuration.'); if(response.status===429) throw new Error('Qloo rate limit reached. Please try again later.'); throw new Error(`Qloo returned an error (${response.status}). Please try again later.`); } const text=await response.text(); if(text.length>1000000) throw new Error('Qloo response exceeded the allowed size.'); let data; try { data=JSON.parse(text); } catch { throw new Error('Qloo returned an unreadable response.'); } if(data?.success===false) throw new Error('Qloo could not complete this request.'); return data; }; }
export default { async fetch(req,env) { const url=new URL(req.url), path=url.pathname, key=(env.QLOO_API_KEY || '').trim(); if(req.method==='GET'&&path==='/api/status') return json(200,{configured:Boolean(key),planner:'deterministic'}); if((req.method==='GET'||req.method==='HEAD')&&assets[path]) return new Response(req.method==='HEAD'?null:assets[path],{headers:{'content-type':contentTypes[path],'x-content-type-options':'nosniff','cache-control':'no-store'}}); if(req.method!=='POST'||!['/api/search','/api/plan','/api/repair'].includes(path)) return json(404,{error:'Not found.'}); if(tooMany(req.headers.get('cf-connecting-ip'))) return json(429,{error:'Too many requests. Please wait a minute.'}); try { const origin=req.headers.get('origin'); if(origin && origin!==url.origin) return json(403,{error:'Invalid request origin.'}); const raw=await req.text(); if(raw.length>50000) return json(413,{error:'Request is too large.'}); let body; try { body=JSON.parse(raw); } catch { throw new Error('Request must contain valid JSON.'); } if(!body||typeof body!=='object'||Array.isArray(body)) throw new Error('Request must contain a JSON object.'); const secret=key || 'fictional-demo-only'; let initialSession; if(path==='/api/repair') { initialSession=await openToken(body.sessionId,secret); body.sessionId=initialSession.id; } const planner=createPlanner({request:qloo(key),configured:Boolean(key),initialSession}); const result=await planner[path.slice(5)](body); if(path!=='/api/search') result.sessionId=await seal(planner.getSession(result.sessionId),secret); return json(200,result); } catch(e) { return json(400,{error:e.message||'Could not create the sidequest.'}); } } };
'''
output = 'const assets = ' + json.dumps(assets, ensure_ascii=False) + ';\n' + planner + '\n' + wrapper
(Path(__file__).parent / 'worker' / 'index.js').write_text(output, encoding='utf-8')
